src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) «Текущая версия кэша» v702 → v703
old_cache = '> **Текущая версия кэша:** `kipia-test-v702`'
new_cache = '> **Текущая версия кэша:** `kipia-test-v703`'
