# (д) ожидание тестов kip8test 5630 → 5673 (kip8 не менялся — 5592)
old_exp = '# Ожидается: 5630 passed, 0 failed (kip8test; в kip8 — 5592 passed, 0 failed)'
new_exp = '# Ожидается: 5673 passed, 0 failed (kip8test; в kip8 — 5592 passed, 0 failed)'
