# (е) факт-строка «Тесты» в таблице раздела (устарела с Task 448:
# 4509 тестов / 146 файлов) → актуальные 5673 / 187
old_cnt = '(`tests/`, 4509 тестов, 146 тест-файлов, `node tests/run-all.js`)'
