# проверки
checks = [
    ('post-Task 479', 1),
    ('kipia-test-v703', 3),   # кэш + пример «Инкрементируй» + строка 3 (Текущее состояние)
    ('devPprStatusClass', None),
    ('5673 passed, 0 failed (kip8test', 1),
    ('СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 480', None),
    ('dev-ppr-warn', None),
    ('post-Task 478', 1),      # строка 4 (предыдущая)
    ('столбец «Дата»', None),
]
for marker, cnt in checks:
    c = src.count(marker)
